export class OrderTableGateway {
  constructor(private readonly db: Knex) {}

  async findById(orderId: string): Promise<Record<string, any> | null> {
    return this.db("orders").where({ id: orderId }).first();
  }

  async findItemsByOrderId(orderId: string): Promise<Array<Record<string, any>>> {
    return this.db("order_items").where({ order_id: orderId });
  }

  async updateStatus(orderId: string, status: string): Promise<void> {
    await this.db("orders").where({ id: orderId }).update({ status, updated_at: new Date() });
  }
}

// Active Record: Business logic and SQL persistence bound to table structure
export class OrderRecord extends BaseActiveRecord {
  public id!: string;
  public customerId!: string;
  public totalAmount!: number;
  public status!: "PENDING" | "PAID" | "SHIPPED";

  // Business logic embedded inside persistence entity
  public cancelOrder(): void {
    if (this.status === "SHIPPED") {
      throw new Error("Cannot cancel an order that has already shipped.");
    }
    this.status = "CANCELLED";
    // Persistence call embedded directly inside entity method
    this.save(); 
  }
}

// Pure Domain Entity: Zero persistence dependencies or ORM imports
export class Order {
  constructor(
    public readonly id: OrderId,
    private status: OrderStatus,
    private readonly items: OrderItem[],
    private version: number
  ) {}

  public allocate(): void {
    if (this.status !== OrderStatus.PENDING) {
      throw new DomainInvariantViolation("Only pending orders can be allocated.");
    }
    this.status = OrderStatus.ALLOCATED;
  }

  // Getters for mapper hydration without exposing internal mutation
  public snapshot(): OrderSnapshot {
    return { id: this.id.value, status: this.status, version: this.version };
  }
}

export class IdentityMap {
  private readonly entities = new Map<string, any>();

  private buildKey(entityClass: string, id: string): string {
    return `${entityClass}:${id}`;
  }

  public get<T>(entityClass: string, id: string): T | undefined {
    return this.entities.get(this.buildKey(entityClass, id));
  }

  public set<T>(entityClass: string, id: string, entity: T): void {
    this.entities.set(this.buildKey(entityClass, id), entity);
  }

  public clear(): void {
    this.entities.clear();
  }
}

export class UnitOfWork {
  private readonly newEntities = new Set<any>();
  private readonly dirtyEntities = new Set<any>();
  private readonly deletedEntities = new Set<any>();
  public readonly identityMap = new IdentityMap();

  constructor(private readonly db: Knex, private readonly mapperRegistry: MapperRegistry) {}

  public registerNew(entity: any): void {
    this.newEntities.add(entity);
  }

  public registerDirty(entity: any): void {
    if (!this.newEntities.has(entity)) {
      this.dirtyEntities.add(entity);
    }
  }

  public async commit(): Promise<void> {
    await this.db.transaction(async (trx) => {
      // 1. Topological Insert: Parents before Children
      for (const entity of this.newEntities) {
        const mapper = this.mapperRegistry.getMapper(entity.constructor.name);
        await mapper.insert(entity, trx);
      }

      // 2. Batch Updates with Optimistic Lock Verification
      for (const entity of this.dirtyEntities) {
        const mapper = this.mapperRegistry.getMapper(entity.constructor.name);
        const affectedRows = await mapper.update(entity, trx);
        if (affectedRows === 0) {
          throw new OptimisticConcurrencyConflict(
            `Concurrent modification detected on ${entity.constructor.name} ID ${entity.id}`
          );
        }
      }

      // 3. Batch Deletes: Children before Parents
      for (const entity of this.deletedEntities) {
        const mapper = this.mapperRegistry.getMapper(entity.constructor.name);
        await mapper.delete(entity, trx);
      }
    });

    // Reset session tracking buffers upon transaction success
    this.newEntities.clear();
    this.dirtyEntities.clear();
    this.deletedEntities.clear();
  }
}

export class WarehouseStockDataMapper {
  async update(stock: WarehouseStock, trx: Knex.Transaction): Promise<number> {
    const currentVersion = stock.version;
    const newVersion = currentVersion + 1;

    // Concurrency invariant: Update only succeeds if version matches the in-memory read token
    const rows = await trx("warehouse_stocks")
      .where({ id: stock.id, version: currentVersion })
      .update({
        quantity_available: stock.quantityAvailable,
        quantity_reserved: stock.quantityReserved,
        version: newVersion,
        updated_at: new Date()
      });

    if (rows > 0) {
      stock.bumpVersion(newVersion);
    }
    return rows;
  }
}
